#!/usr/bin/env python3
# libxmq - Copyright (C) 2026 Fredrik Öhrström (spdx: MIT)
#
# Generate src/main/c/parts/xml_chars.c from the libxml2 sources in 3rdparty/libxml2:
# the XML 1.0 (4th edition) character classes BaseChar, Ideographic, CombiningChar,
# Digit and Extender (codegen/ranges.inc and include/libxml/chvalid.h). They are used
# by the xpath name scanner, like libxml2 IS_LETTER, IS_DIGIT, IS_COMBINING, IS_EXTENDER.
# The tables are copied from libxml2, the generated file carries the libxml2 notice.
#
# Usage: scripts/generate_xml_char_tables.py [libxml2_dir] [output_file]

import os
import re
import sys

root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
libxml2 = sys.argv[1] if len(sys.argv) > 1 else os.path.join(root, '3rdparty', 'libxml2')
out_file = sys.argv[2] if len(sys.argv) > 2 else os.path.join(root, 'src', 'main', 'c', 'parts', 'xml_chars.c')

ranges = open(os.path.join(libxml2, 'codegen', 'ranges.inc'), encoding='utf-8').read()
copyright = open(os.path.join(libxml2, 'Copyright'), encoding='utf-8').read()
notice = copyright[copyright.index(' Copyright (C) 1998-2012'):].rstrip('\n')
version = re.search(r'LIBXML_DOTTED_VERSION "([^"]+)"',
                    open(os.path.join(libxml2, 'include', 'libxml', 'xmlversion.h'), encoding='utf-8').read()).group(1)

def table(name, kind):
    m = re.search(r'static const xmlCh%sRange %s_%srng\[\] = \{(.*?)\};' % (kind, name, kind.lower()), ranges, re.S)
    if not m:
        return []
    return [(int(a, 16), int(b, 16)) for a, b in re.findall(r'\{(0x[0-9a-fA-F]+),\s*(0x[0-9a-fA-F]+)\}', m.group(1))]

classes = {}
for cls in ['BaseChar', 'Combining', 'Digit', 'Extender']:
    name = 'xmlIs' + cls
    classes[cls] = table(name, 'S') + table(name, 'L')
    assert classes[cls], 'no ranges for ' + cls

o = []
o.append('''/* Generated by scripts/generate_xml_char_tables.py from libxml2 ''' + version + ''' (codegen/ranges.inc,
   include/libxml/chvalid.h). Do not edit, regenerate instead.
   The tables are copied from libxml2, which is covered by the following notice
   (from libxml2/Copyright):

''' + notice + '''
*/

#ifndef BUILDING_DIST_XMQ

#include"xml_chars.h"

#endif

#ifdef XML_CHARS_MODULE

typedef struct
{
    unsigned int low;
    unsigned int high;
} XmlCharRange;

''')
for cls, rs in classes.items():
    o.append('static const XmlCharRange xml_char_%s[] = {\n' % cls.lower())
    for i in range(0, len(rs), 4):
        o.append('    ' + ' '.join('{ 0x%x, 0x%x },' % r for r in rs[i:i+4]) + '\n')
    o.append('};\n\n')
o.append('''static bool xml_char_in(unsigned int c, const XmlCharRange *r, size_t n)
{
    size_t low = 0, high = n;
    while (low < high)
    {
        size_t mid = low + (high - low) / 2;
        if (c < r[mid].low) high = mid;
        else if (c > r[mid].high) low = mid + 1;
        else return true;
    }
    return false;
}

#define XML_CHAR_IN(c, table) xml_char_in((unsigned int)(c), table, sizeof(table) / sizeof(table[0]))

bool xml_char_is_base_char(int c)
{
    if (c < 0x100)
    {
        return (c >= 0x41 && c <= 0x5a) || (c >= 0x61 && c <= 0x7a) ||
               (c >= 0xc0 && c <= 0xd6) || (c >= 0xd8 && c <= 0xf6) || (c >= 0xf8);
    }
    return XML_CHAR_IN(c, xml_char_basechar);
}

bool xml_char_is_ideographic(int c)
{
    if (c < 0x100) return false;
    return (c >= 0x4e00 && c <= 0x9fa5) || c == 0x3007 || (c >= 0x3021 && c <= 0x3029);
}

bool xml_char_is_letter(int c)
{
    return xml_char_is_base_char(c) || xml_char_is_ideographic(c);
}

bool xml_char_is_digit(int c)
{
    if (c < 0x100) return c >= 0x30 && c <= 0x39;
    return XML_CHAR_IN(c, xml_char_digit);
}

bool xml_char_is_combining(int c)
{
    if (c < 0x100) return false;
    return XML_CHAR_IN(c, xml_char_combining);
}

bool xml_char_is_extender(int c)
{
    if (c < 0x100) return c == 0xb7;
    return XML_CHAR_IN(c, xml_char_extender);
}

#endif // XML_CHARS_MODULE
''')
open(out_file, 'w', encoding='utf-8').write(''.join(o))
print('wrote %s: %s' % (out_file, ', '.join('%s %d ranges' % (k, len(v)) for k, v in classes.items())))
